# El doble SQLite marca los fallos de validación como transacciones no confirmadas,
# igual que SQLite real: cada begin tiene su propia confirmación.
fixtures['android/database/sqlite/SQLiteDatabase.java']=fixtures['android/database/sqlite/SQLiteDatabase.java'].replace('int depth;boolean failed;', 'int depth;boolean failed;java.util.Deque<Boolean> commits=new java.util.ArrayDeque<>();').replace('if(depth++==0){backup=', 'commits.push(false);if(depth++==0){backup=').replace('public void setTransactionSuccessful(){}','public void setTransactionSuccessful(){commits.pop();commits.push(true);}').replace('public void endTransaction(){if(--depth==0&&failed)data=backup;}', 'public void endTransaction(){if(!commits.pop())failed=true;if(--depth==0&&failed)data=backup;}')
